import copy
(n, k) = map(int, input().split())
li = list(map(int, input()))
copyli = copy.copy(li)
for y in range(k):
	for x in range(y, n, k):
		li[x] = li[y]
print(n)
if copyli > li:
	pos = k - 1
	while li[pos] == 9 and pos > 0:
		pos = pos - 1
	ele = li[pos] + 1
	for x in range(pos, n, k):
		li[x] = ele
	for y in range(pos + 1, k):
		for x in range(y, n, k):
			li[x] = 0
for i in li:
	print(i, end='')
